    public async Task<object> RunAutomation(string owner, CancellationToken token)
    {
        var started=Now();if(!await _automationGate.WaitAsync(0,token))return new{startedAt=started,completedAt=Now(),chargesCreated=0,providerEventsProcessed=0,notificationsCompleted=0,notificationsFailed=0,alreadyRunning=true};
        try
        {
            var schedules=await Schedules(owner,token);var created=0;
            foreach(var item in schedules.Where(value=>Property(value,"enabled")=="True"&&string.CompareOrdinal(Property(value,"nextChargeDate"),DateTimeOffset.UtcNow.ToString("yyyy-MM-dd"))<=0))
            {
                var scheduleId=Property(item,"id")!;var chargeDate=Property(item,"nextChargeDate")!;if(!await ClaimScheduleRun(scheduleId,chargeDate,token))continue;
                try
                {
                    var input=JsonSerializer.SerializeToElement(new{propertyId=Property(item,"propertyId"),leaseId=Property(item,"leaseId"),description=Property(item,"descriptionTemplate")!.Replace("{{month}}",DateTimeOffset.UtcNow.ToString("MMMM yyyy")),amountCents=Long(item,"amountCents"),dueDate=chargeDate});
                    var charge=await CreateCharge(input,owner,token);created++;
                    await using var advance=database.CreateCommand("WITH advanced AS (UPDATE property_rent_schedules SET next_charge_date=($2::date+interval '1 month')::date::text,updated_at=$3 WHERE id=$1 RETURNING id) UPDATE property_rent_schedule_runs SET status='completed',charge_id=$4,completed_at=$3,error=NULL WHERE schedule_id=$1 AND charge_date=$2 AND EXISTS(SELECT 1 FROM advanced)");advance.Parameters.AddWithValue(scheduleId);advance.Parameters.AddWithValue(chargeDate);advance.Parameters.AddWithValue(Now());advance.Parameters.AddWithValue(Property(charge,"id")!);await advance.ExecuteNonQueryAsync(token);
                    var reminderDays=item.GetType().GetProperty("reminderDays")?.GetValue(item) as int[]??[];try{await EnqueueChargeReminders(Property(charge,"id")!,reminderDays,token);}catch{/* Charge creation is durable; a later run can repair reminder delivery without duplicating rent. */}
                }
                catch(Exception error){await FailScheduleRun(scheduleId,chargeDate,error.Message,token);}
            }
            var events=await ProcessProviderEvents(token);var notifications=await ProcessNotifications(owner,token);
            return new{startedAt=started,completedAt=Now(),chargesCreated=created,providerEventsProcessed=events,notificationsCompleted=notifications.Completed,notificationsFailed=notifications.Failed,alreadyRunning=false};
        }
        finally{_automationGate.Release();}
    }
