    {await using var command=database.CreateCommand("INSERT INTO property_rent_schedule_runs(id,schedule_id,charge_date,status,created_at) VALUES($1,$2,$3,'running',$4) ON CONFLICT(schedule_id,charge_date) DO NOTHING");command.Parameters.AddWithValue(Guid.NewGuid().ToString());command.Parameters.AddWithValue(schedule);command.Parameters.AddWithValue(chargeDate);command.Parameters.AddWithValue(Now());return await command.ExecuteNonQueryAsync(token)==1;}
