    private async Task<int> ProcessProviderEvents(CancellationToken token)
    {
        var completed=0;
        for(var count=0;count<100;count++)
        {
            await using var claim=database.CreateCommand("WITH candidate AS (SELECT id FROM property_provider_events WHERE status='queued' ORDER BY created_at FOR UPDATE SKIP LOCKED LIMIT 1) UPDATE property_provider_events e SET status='running',attempts=e.attempts+1 FROM candidate WHERE e.id=candidate.id RETURNING e.id,e.provider,e.event_type,e.payload_json,e.attempts");
            await using var reader=await claim.ExecuteReaderAsync(token);if(!await reader.ReadAsync(token))break;var id=reader.GetString(0);var provider=reader.GetString(1);var eventType=reader.GetString(2);var payload=reader.GetString(3);var attempts=reader.GetInt64(4);await reader.CloseAsync();
            try{await paymentGateway.ApplyProviderEventAsync(provider,eventType,payload,token);await SetProviderEventStatus(id,"completed",null,true,token);completed++;}
            catch(Exception error){await SetProviderEventStatus(id,attempts>=5?"failed":"queued",error.Message,attempts>=5,token);}
        }
        return completed;
    }
    public Task<int> ProcessProviderEventsNow(CancellationToken token)=>ProcessProviderEvents(token);
