    {await using var command=database.CreateCommand("UPDATE property_provider_events SET status=$2,last_error=$3,processed_at=CASE WHEN $4 THEN $5 ELSE NULL END WHERE id=$1");command.Parameters.AddWithValue(id);command.Parameters.AddWithValue(status);AddNullable(command,error);command.Parameters.AddWithValue(terminal);command.Parameters.AddWithValue(Now());await command.ExecuteNonQueryAsync(token);}
    private async Task<(int Completed,int Failed)> ProcessNotifications(string owner,CancellationToken token)
    {
        var completed=0;var failed=0;
        for(var count=0;count<100;count++)
        {
            const string sql="WITH candidate AS (SELECT n.id FROM property_notification_jobs n JOIN property_organizations o ON o.id=n.organization_id WHERE o.owner_user_id=$1 AND n.status='queued' AND n.scheduled_at::timestamptz<=now() AND n.next_attempt_at::timestamptz<=now() ORDER BY n.scheduled_at,n.created_at FOR UPDATE OF n SKIP LOCKED LIMIT 1) UPDATE property_notification_jobs n SET status='running',attempts=n.attempts+1 FROM candidate WHERE n.id=candidate.id RETURNING n.id,n.tenant_id,n.channel,n.recipient,n.subject,n.body,n.attempts,n.max_attempts";
            await using var claim=database.CreateCommand(sql);claim.Parameters.AddWithValue(owner);await using var reader=await claim.ExecuteReaderAsync(token);if(!await reader.ReadAsync(token))break;var id=reader.GetString(0);var tenant=reader.IsDBNull(1)?null:reader.GetString(1);var channel=reader.GetString(2);var recipient=reader.GetString(3);var subject=reader.GetString(4);var body=reader.GetString(5);var attempts=reader.GetInt64(6);var maxAttempts=reader.GetInt64(7);await reader.CloseAsync();
            try
            {
                string provider;string? providerId=null;string deliveryStatus="succeeded";string? deliveryError=null;
                if(channel=="in_app")provider="local";
                else if(channel=="email")
                {var connection=settings.Current().PropertyIntegrationsValue.GmailConnectionId;if(string.IsNullOrWhiteSpace(connection))throw new InvalidOperationException("Gmail reminder account is not configured");var sent=await gmail.SendAsync(connection,owner,JsonSerializer.SerializeToElement(new{to=new[]{recipient},cc=Array.Empty<string>(),bcc=Array.Empty<string>(),subject,bodyText=body}),token);provider="gmail";providerId=Property(sent,"id");}
                else if(!await CanSendSms(tenant,recipient,token)){provider="consent";deliveryStatus="suppressed";deliveryError="SMS consent is not active";}
                else{provider="twilio";providerId=await SendSms(recipient,body,token);}
                await CompleteNotification(id,provider,providerId,deliveryStatus,deliveryError,token);completed++;
            }
            catch(Exception error){await FailNotification(id,attempts,maxAttempts,error.Message,token);failed++;}
        }
        return(completed,failed);
    }
    private async Task EnqueueChargeReminders(string chargeId,int[] reminderDays,CancellationToken token)
    {
        const string sql="SELECT c.due_date,c.description,c.amount_cents,p.organization_id,p.name,t.id,t.linked_user_id,t.first_name,t.email,t.phone FROM property_rent_charges c JOIN managed_properties p ON p.id=c.property_id LEFT JOIN property_leases l ON l.id=c.lease_id LEFT JOIN property_tenants t ON t.id=l.tenant_id WHERE c.id=$1";
        await using var command=database.CreateCommand(sql);command.Parameters.AddWithValue(chargeId);await using var reader=await command.ExecuteReaderAsync(token);if(!await reader.ReadAsync(token)||reader.IsDBNull(5))return;var due=DateOnly.Parse(reader.GetString(0));var description=reader.GetString(1);var amount=reader.GetInt64(2);var org=reader.GetString(3);var property=reader.GetString(4);var tenant=reader.GetString(5);var linked=reader.IsDBNull(6)?null:reader.GetString(6);var first=reader.GetString(7);var email=reader.GetString(8);var phone=reader.GetString(9);await reader.CloseAsync();
        foreach(var offset in reminderDays.Distinct())
        {var scheduled=due.AddDays(offset).ToDateTime(new TimeOnly(9,0),DateTimeKind.Utc).ToString("O");var timing=offset<0?$"due in {Math.Abs(offset)} day{(Math.Abs(offset)==1?"":"s")}":offset==0?"due today":$"{offset} day{(offset==1?"":"s")} overdue";var subject=$"Rent reminder: {property} is {timing}";var body=$"Hello {first},\n\n{description} for {property} is {timing}. Amount: {(amount/100m):C}. Due date: {due:yyyy-MM-dd}.\n\nPlease use the tenant portal to review your balance or payment options.";if(linked is not null)await EnqueueNotification(org,tenant,chargeId,"in_app",linked,subject,body,scheduled,$"rent-reminder:{chargeId}:{offset}:in_app",token);if(!string.IsNullOrWhiteSpace(email))await EnqueueNotification(org,tenant,chargeId,"email",email,subject,body,scheduled,$"rent-reminder:{chargeId}:{offset}:email",token);if(!string.IsNullOrWhiteSpace(phone)&&await CanSendSms(tenant,phone,token))await EnqueueNotification(org,tenant,chargeId,"sms",phone,subject,body,scheduled,$"rent-reminder:{chargeId}:{offset}:sms",token);}
    }
