    public Task<IReadOnlyList<object>> Backups(CancellationToken token)
    {
        var root=Path.Combine(active.DataDirectory,"backups");Directory.CreateDirectory(root);token.ThrowIfCancellationRequested();var result=new List<object>();
        foreach(var path in Directory.EnumerateDirectories(root,"property-*")){var databaseFile=Path.Combine(path,"database.dump");var totals=TreeSize(path);var info=new DirectoryInfo(path);result.Add(new{id=info.Name,createdAt=info.CreationTimeUtc.ToString("O"),sizeBytes=totals.Bytes,databaseBytes=File.Exists(databaseFile)?new FileInfo(databaseFile).Length:0,fileCount=totals.Files});}
        foreach(var path in Directory.EnumerateFiles(root,"property-*.dump")){var file=new FileInfo(path);result.Add(new{id=Path.GetFileNameWithoutExtension(path),createdAt=file.CreationTimeUtc.ToString("O"),sizeBytes=file.Length,databaseBytes=file.Length,fileCount=1});}
        return Task.FromResult<IReadOnlyList<object>>(result.OrderByDescending(value=>Property(value,"createdAt")).ToArray());
    }
    public async Task<object> CreateBackup(CancellationToken token)
    {
