        foreach(var folder in new[]{"property-files","property-photos","data-protection-keys"}){var source=Path.Combine(active.DataDirectory,folder);if(Directory.Exists(source))CopyDirectory(source,Path.Combine(destination,folder),token);}
        var settingsPath=Path.Combine(active.DataDirectory,"app-settings.protected.json");if(File.Exists(settingsPath))File.Copy(settingsPath,Path.Combine(destination,Path.GetFileName(settingsPath)),true);
