        var retention=int.TryParse(Environment.GetEnvironmentVariable("PROPERTY_BACKUP_RETENTION"),out var configured)?Math.Max(1,configured):7;foreach(var old in Directory.EnumerateDirectories(root,"property-*").OrderByDescending(path=>path,StringComparer.Ordinal).Skip(retention))Directory.Delete(old,true);
