    private async Task<List<object>> Documents(string owner, string user, CancellationToken token) => await Rows("SELECT d.id,d.organization_id,d.property_id,p.name,d.lease_id,d.tenant_id,d.title,d.category,d.visibility,d.requires_acknowledgement<>0,ack.acknowledged_at,v.id,v.version,v.filename,v.content_type,v.size_bytes,v.sha256,v.created_at,d.created_at,d.updated_at FROM property_documents d JOIN managed_properties p ON p.id=d.property_id JOIN LATERAL(SELECT * FROM property_document_versions WHERE document_id=d.id ORDER BY version DESC LIMIT 1)v ON true LEFT JOIN property_document_acknowledgements ack ON ack.document_id=d.id AND ack.user_id=$2 WHERE p.owner_user_id=$1 AND ($1=$2 OR d.visibility='tenant')", [owner, user], r => new { id = r.GetString(0), organizationId = r.GetString(1), propertyId = r.GetString(2), propertyName = r.GetString(3), leaseId = r.IsDBNull(4) ? null : r.GetString(4), tenantId = r.IsDBNull(5) ? null : r.GetString(5), title = r.GetString(6), category = r.GetString(7), visibility = r.GetString(8), requiresAcknowledgement = r.GetBoolean(9), acknowledgedAt = r.IsDBNull(10) ? null : r.GetString(10), latestVersion = new { id = r.GetString(11), documentId = r.GetString(0), version = r.GetInt64(12), filename = r.GetString(13), contentType = r.GetString(14), sizeBytes = r.GetInt64(15), sha256 = r.GetString(16), createdAt = r.GetString(17) }, createdAt = r.GetString(18), updatedAt = r.GetString(19) }, token);
